<template><div class="page-head"><div><h2>商品配置</h2><div class="muted">维护商品信息、价格、库存和展示状态</div></div><ElButton type="warning" @click="edit()">新增商品</ElButton></div><ElCard><ElTable :data="rows" v-loading="loading"><ElTableColumn label="商品" min-width="260"><template #default="s"><div class="goods"><ElImage :src="s.row.coverUrl" fit="cover"/><div><b>{{s.row.name}}</b><small>{{s.row.categoryName||'未分类'}}</small></div></div></template></ElTableColumn><ElTableColumn label="售价" width="110"><template #default="s">¥{{s.row.salePriceYuan}}</template></ElTableColumn><ElTableColumn prop="stock" label="库存" width="90"/><ElTableColumn prop="salesCount" label="销量" width="90"/><ElTableColumn label="推荐" width="130"><template #default="s"><ElTag v-if="s.row.hot" type="danger">爆款</ElTag><ElTag v-if="s.row.isNew" type="success" style="margin-left:4px">新品</ElTag></template></ElTableColumn><ElTableColumn label="状态" width="90"><template #default="s"><ElTag :type="s.row.status===1?'success':'info'">{{s.row.status===1?'上架':'下架'}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="100"><template #default="s"><ElButton link type="warning" @click="edit(s.row)">编辑</ElButton></template></ElTableColumn></ElTable></ElCard><ElDialog v-model="visible" :title="form.id?'编辑商品':'新增商品'" width="760px" top="4vh"><ElForm label-position="top" class="product-form"><ElFormItem label="商品名称"><ElInput v-model="form.name"/></ElFormItem><ElFormItem label="商品分类"><ElSelect v-model="form.categoryId" style="width:100%"><ElOption v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></ElSelect></ElFormItem><ElFormItem label="商品主图"><div class="upload-row"><ElImage v-if="form.coverUrl" :src="form.coverUrl" fit="cover" class="cover"/><ElInput v-model="form.coverUrl" placeholder="上传后自动填写地址"/><ElUpload :show-file-list="false" accept="image/*" :http-request="upload"><ElButton :loading="uploading">上传</ElButton></ElUpload></div></ElFormItem><div class="two"><ElFormItem label="售价（元）"><ElInputNumber v-model="form.salePrice" :precision="2" :min="0"/></ElFormItem><ElFormItem label="市场价（元）"><ElInputNumber v-model="form.marketPrice" :precision="2" :min="0"/></ElFormItem><ElFormItem label="库存"><ElInputNumber v-model="form.stock" :min="0"/></ElFormItem><ElFormItem label="显示销量"><ElInputNumber v-model="form.salesCount" :min="0"/></ElFormItem></div><ElFormItem label="商品介绍"><ElInput v-model="form.description" type="textarea" :rows="3"/></ElFormItem><ElFormItem label="购买须知"><ElInput v-model="form.purchaseNotice" type="textarea" :rows="2"/></ElFormItem><div class="switches"><ElFormItem label="爆款商品"><ElSwitch v-model="form.hot"/></ElFormItem><ElFormItem label="新品推荐"><ElSwitch v-model="form.isNew"/></ElFormItem><ElFormItem label="上架销售"><ElSwitch v-model="form.enabled"/></ElFormItem><ElFormItem label="排序"><ElInputNumber v-model="form.sortNo" :min="0"/></ElFormItem></div></ElForm><template #footer><ElButton @click="visible=false">取消</ElButton><ElButton type="warning" :loading="saving" @click="save">保存</ElButton></template></ElDialog></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'../api';const rows=ref<any[]>([]),categories=ref<any[]>([]),loading=ref(false),visible=ref(false),saving=ref(false),uploading=ref(false);const blank=()=>({id:null,categoryId:null,name:'',coverUrl:'',salePrice:0,marketPrice:0,stock:0,salesCount:0,description:'',purchaseNotice:'',hot:false,isNew:false,enabled:true,sortNo:0});const form=reactive<any>(blank());async function load(){loading.value=true;try{[rows.value,categories.value]=await Promise.all([api.products(),api.categories()]) as any}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}async function edit(row?:any){Object.assign(form,blank());if(row){const d:any=await api.product(row.id);Object.assign(form,d,{salePrice:d.salePriceYuan,marketPrice:d.marketPriceYuan,enabled:d.status===1})}visible.value=true}async function upload(o:any){uploading.value=true;try{const d:any=await api.upload(o.file);form.coverUrl=d.url;ElMessage.success('上传成功')}catch(e:any){ElMessage.error(e.message)}finally{uploading.value=false}}async function save(){if(!form.name||!form.categoryId||!form.coverUrl)return ElMessage.warning('请填写名称、分类并上传主图');saving.value=true;try{await api.saveProduct({...form,galleryUrls:[]});visible.value=false;await load();ElMessage.success('保存成功')}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}onMounted(load)</script><style scoped>.goods{display:flex;align-items:center;gap:12px}.goods .el-image{width:58px;height:58px;border-radius:10px}.goods b,.goods small{display:block}.goods small{color:#999;margin-top:6px}.upload-row{display:flex;align-items:center;gap:10px;width:100%}.cover{width:76px;height:76px;border-radius:12px;flex:none}.two,.switches{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.product-form{max-height:65vh;overflow:auto;padding-right:8px}</style>
